    private void expectReject(String consumer,byte[] bytes,String reason,String messageId)throws Exception{String sha=sha256(bytes),key=consumer+":"+sha;Rejected expected=rejected.get(key);if(expected==null){expected=new Rejected(consumer,sha,bytes.length,reason,messageId);rejected.put(key,expected);}else require(expected.reason.equals(reason)&&Objects.equals(expected.messageId,messageId),"duplicate_rejection_metadata_contract_is_consistent");expected.copies++;send(bytes,consumer.equals("FILE_FINALIZE")?"file.finalize":"evidence.anchor",messageId);}
    private void send(byte[] body,String routing,String messageId)throws Exception{var properties=new MessageProperties();properties.setDeliveryMode(MessageDeliveryMode.PERSISTENT);properties.setContentType("application/json");if(messageId!=null)properties.setMessageId(messageId);var correlation=new CorrelationData(UUID.randomUUID().toString());rabbit.send(exchange,routing,new Message(body,properties),correlation);var confirm=correlation.getFuture().get(10,TimeUnit.SECONDS);require(confirm.ack()&&correlation.getReturned()==null,"actual_probe_publish_confirmed_and_routed");}
