    private List<Map<String,Object>> consumerDetails(String queue){try{return objects(management("/api/queues/"+encode(env("RABBITMQ_VIRTUAL_HOST","/"))+"/"+encode(queue)).get("consumer_details"));}catch(Exception failure){throw new ProbeFailure("cannot_read_own_real_consumer_configuration");}}
    private long queueMessages(String queue){try{var data=management("/api/queues/"+encode(env("RABBITMQ_VIRTUAL_HOST","/"))+"/"+encode(queue));return Math.max(ready(queue),number(data.get("messages_ready")))+number(data.get("messages_unacknowledged"));}catch(Exception failure){throw new ProbeFailure("cannot_read_owned_queue_delivery_counts");}}
