    private Account owner(){return accounts.getFirst();}private Account admin(){return accounts.get(1);}private Account uploader(){return accounts.get(2);}
    private static String env(String key,String fallback){String value=System.getenv(key);if(value==null||value.isBlank()){if(fallback==null)throw new ProbeFailure("missing_required_environment");return fallback;}return value;}private static long version(Map<String,Object> row){return number(row.get("lockVersion"));}private static long number(Object value){if(!(value instanceof Number n))throw new ProbeFailure("expected_number");return n.longValue();}private static String string(Object value){if(!(value instanceof String text))throw new ProbeFailure("expected_string");return text;}private static Instant instant(Object value){if(value instanceof java.time.LocalDateTime t)return t.toInstant(java.time.ZoneOffset.UTC);if(value instanceof java.sql.Timestamp t)return t.toInstant();if(value instanceof Instant t)return t;throw new ProbeFailure("expected_jdbc_utc_timestamp");}
    @SuppressWarnings("unchecked")private static Map<String,Object> object(Object value){if(!(value instanceof Map))throw new ProbeFailure("expected_object");return (Map<String,Object>)value;}private static List<Map<String,Object>> objects(Object value){if(!(value instanceof List<?> list))throw new ProbeFailure("expected_array");return list.stream().map(MessagingReliabilityProbe::object).toList();}private static String sha256(byte[] bytes)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}private static void frame(MessageDigest digest,String value){byte[] bytes=value==null?null:value.getBytes(StandardCharsets.UTF_8);digest.update(ByteBuffer.allocate(4).putInt(bytes==null?-1:bytes.length).array());if(bytes!=null)digest.update(bytes);}
    private static byte[] png(int color)throws Exception{var image=new BufferedImage(8,8,BufferedImage.TYPE_INT_RGB);for(int x=0;x<8;x++)for(int y=0;y<8;y++)image.setRGB(x,y,color);var output=new ByteArrayOutputStream();if(!ImageIO.write(image,"png",output))throw new ProbeFailure("png_encoder_unavailable");return output.toByteArray();}
    private static final class Account{final String id,username,password;String token;Account(String id,String username,String password){this.id=id;this.username=username;this.password=password;}@Override public String toString(){return "AuditAccount["+id+"]";}}private record Scope(String task,String requirement,String subtask,String execution){}private record Reply(int status,Map<String,Object> body){Map<String,Object> data(){return object(body.get("data"));}@Override public String toString(){return "AuditReply["+status+"]";}}private static final class ProbeFailure extends RuntimeException{ProbeFailure(String name){super(name);}}
    private void await(BooleanSupplier condition,String name)throws Exception {long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(40);while(System.nanoTime()<deadline){if(condition.getAsBoolean()){require(true,name);return;}Thread.sleep(100);}require(false,name);}
    private void awaitSeconds(BooleanSupplier condition,String name,int seconds)throws Exception {long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(seconds);while(System.nanoTime()<deadline){if(condition.getAsBoolean()){require(true,name);return;}Thread.sleep(100);}require(false,name);}
    private static byte[] blob(Object value)throws Exception{if(value instanceof byte[] bytes)return bytes;if(value instanceof java.sql.Blob blob)return blob.getBytes(1,(int)blob.length());throw new ProbeFailure("expected_binary_checkpoint");}
    private long count(String sql,Object...args){Long value=jdbc.queryForObject(sql,Long.class,args);if(value==null)throw new ProbeFailure("missing_sql_count");return value;}
    private Map<String,Long> businessCounts(){Map<String,Long> result=new LinkedHashMap<>();TABLE_ORDER.keySet().forEach(t->result.put(t,count("SELECT COUNT(*) FROM "+t)));return result;}
    private byte[] businessSnapshot()throws Exception {
        MessageDigest digest=MessageDigest.getInstance("SHA-256");try(Connection connection=dataSource.getConnection()){
            for(var table:TABLE_ORDER.entrySet()){frame(digest,table.getKey());try(var statement=connection.createStatement();ResultSet rows=statement.executeQuery("SELECT * FROM "+table.getKey()+" ORDER BY "+table.getValue())){
                while(rows.next()){digest.update((byte)1);for(int column=1;column<=rows.getMetaData().getColumnCount();column++){
                    int type=rows.getMetaData().getColumnType(column);if(type==java.sql.Types.BINARY||type==java.sql.Types.VARBINARY||type==java.sql.Types.LONGVARBINARY||type==java.sql.Types.BLOB){byte[] bytes=rows.getBytes(column);digest.update(ByteBuffer.allocate(4).putInt(bytes==null?-1:bytes.length).array());if(bytes!=null)digest.update(bytes);}else frame(digest,rows.getString(column));
                }}digest.update((byte)0);
            }}
        }return digest.digest();
    }
    private static final class Rejected{final String consumer,sha,reason,messageId;final long size;int copies;Rejected(String consumer,String sha,long size,String reason,String messageId){this.consumer=consumer;this.sha=sha;this.size=size;this.reason=reason;this.messageId=messageId;}}
    static final class FaultPlan{
        final AtomicBoolean crashAfterConfirm=new AtomicBoolean(),claimBlocked=new AtomicBoolean(),rejectBlocked=new AtomicBoolean(),failNextStorageOpen=new AtomicBoolean(),gateStorage=new AtomicBoolean();
        final AtomicReference<OutboxTransactions.Delivery> claimReplay=new AtomicReference<>();final List<Long> claimFailures=new CopyOnWriteArrayList<>(),rejectionFailures=new CopyOnWriteArrayList<>();final AtomicInteger activeLeaseNullClaims=new AtomicInteger();final CountDownLatch storageGateEntered=new CountDownLatch(1),storageGateRelease=new CountDownLatch(1);volatile Runnable confirmedCallback;
    }
    @TestConfiguration(proxyBeanMethods=false) @Profile("reliability-probe")
    static class FaultConfiguration{
        @Bean FaultPlan reliabilityFaultPlan(){return new FaultPlan();}
        @Bean static BeanPostProcessor reliabilityPauseOwnContainers(){return new BeanPostProcessor(){@Override public Object postProcessBeforeInitialization(Object bean,String name){if(bean instanceof SimpleMessageListenerContainer container)container.setAutoStartup(false);return bean;}};}
        @Bean @Primary FaultOutboxTransactions reliabilityOutboxTransactions(OutboxMapper mapper,FaultPlan plan){return new FaultOutboxTransactions(mapper,plan);}
        @Bean @Primary FaultFinalizationTransactions reliabilityFinalizationTransactions(UploadMapper uploads,FinalizationMapper work,OutboxWriter writer,FaultPlan plan){return new FaultFinalizationTransactions(uploads,work,writer,plan);}
        @Bean @Primary FaultRejectionRecorder reliabilityRejectionRecorder(MessageRejectionMapper mapper,FaultPlan plan){return new FaultRejectionRecorder(mapper,plan);}
        @Bean @Primary FaultStorage reliabilityStorage(@Qualifier("objectStorage") ObjectStorage real,FaultPlan plan){return new FaultStorage(real,plan);}
    }
    static class FaultOutboxTransactions extends OutboxTransactions{
        private final FaultPlan plan;FaultOutboxTransactions(OutboxMapper mapper,FaultPlan plan){super(mapper);this.plan=plan;}
        @Override @Transactional public Delivery claim(){Delivery replay=plan.claimReplay.getAndSet(null);return replay==null?super.claim():replay;}
        @Override @Transactional public boolean sent(Delivery delivery){if(plan.crashAfterConfirm.compareAndSet(true,false)){plan.confirmedCallback.run();Runtime.getRuntime().halt(73);}return super.sent(delivery);}
    }
    static class FaultFinalizationTransactions extends FinalizationTransactions{
        private final FaultPlan plan;FaultFinalizationTransactions(UploadMapper uploads,FinalizationMapper work,OutboxWriter writer,FaultPlan plan){super(uploads,work,writer);this.plan=plan;}
        @Override @Transactional public Claim claim(MessageEvent event,boolean recovery){if(plan.claimBlocked.get()){plan.claimFailures.add(System.nanoTime());throw new DataAccessResourceFailureException("T022_SAFE_INJECTED_DATABASE_UNAVAILABLE");}Claim claim=super.claim(event,recovery);if(claim==null&&plan.gateStorage.get())plan.activeLeaseNullClaims.incrementAndGet();return claim;}
    }
    static class FaultRejectionRecorder extends MessageRejectionRecorder{
        private final FaultPlan plan;FaultRejectionRecorder(MessageRejectionMapper mapper,FaultPlan plan){super(mapper);this.plan=plan;}
        @Override @Transactional(propagation=Propagation.REQUIRES_NEW) public void record(String consumer,byte[] body,String reason,String messageId){if(plan.rejectBlocked.get()){plan.rejectionFailures.add(System.nanoTime());throw new DataAccessResourceFailureException("T022_SAFE_INJECTED_REJECTION_DATABASE_UNAVAILABLE");}super.record(consumer,body,reason,messageId);}
    }
    static final class FaultStorage implements ObjectStorage{
        private final ObjectStorage real;private final FaultPlan plan;FaultStorage(ObjectStorage real,FaultPlan plan){this.real=real;this.plan=plan;}
        @Override public void put(String key,Path file,String type){real.put(key,file,type);}
        @Override public InputStream open(String key){if(key.startsWith("upload-parts/")){if(plan.failNextStorageOpen.compareAndSet(true,false))throw new BusinessException(ErrorCode.DEPENDENCY_UNAVAILABLE);if(plan.gateStorage.get()){plan.storageGateEntered.countDown();try{if(!plan.storageGateRelease.await(35,TimeUnit.SECONDS))throw new IllegalStateException("T022_SAFE_STORAGE_GATE_TIMEOUT");}catch(InterruptedException failure){Thread.currentThread().interrupt();throw new IllegalStateException("T022_SAFE_STORAGE_GATE_INTERRUPTED");}}}return real.open(key);}
        @Override public void delete(String key){real.delete(key);}
    }
